from sqlalchemy import create_engine, select, case
from sqlalchemy.ext.hybrid import hybrid_property
from sqlalchemy.orm import DeclarativeBase, Mapped, mapped_column, Session

class Base(DeclarativeBase): pass
class Account(Base):
    __tablename__ = "accounts"
    id: Mapped[int] = mapped_column(primary_key=True)
    balance: Mapped[int]

    @hybrid_property
    def status(self) -> str:
        return "overdrawn" if self.balance < 0 else "ok"

    @status.inplace.expression
    @classmethod
    def _status_expr(cls):
        return case((cls.balance < 0, "overdrawn"), else_="ok")

engine = create_engine("sqlite://"); Base.metadata.create_all(engine)
with Session(engine) as s:
    s.add_all([Account(balance=50), Account(balance=-5)]); s.commit()
    print(s.get(Account, 2).status)                                   # overdrawn
    print(s.scalars(select(Account.id).where(Account.status == "ok")).all())  # [1]

import json
from sqlalchemy import create_engine, event, select, String
from sqlalchemy.types import TypeDecorator
from sqlalchemy.orm import DeclarativeBase, Mapped, mapped_column, Session

class JSONText(TypeDecorator):
    impl = String
    cache_ok = True
    def process_bind_param(self, value, dialect):
        return None if value is None else json.dumps(value, sort_keys=True)
    def process_result_value(self, value, dialect):
        return None if value is None else json.loads(value)
class Base(DeclarativeBase): pass
class Doc(Base):
    __tablename__ = "docs"
    id: Mapped[int] = mapped_column(primary_key=True)
    meta: Mapped[dict] = mapped_column(JSONText)
@event.listens_for(Doc, "before_insert")
def stamp(mapper, connection, target):
    target.meta = {**target.meta, "v": 1}

engine = create_engine("sqlite://"); Base.metadata.create_all(engine)
with Session(engine) as s:
    s.add(Doc(meta={"tag": "x"})); s.commit()
    print(s.scalar(select(Doc.meta)))  # {'tag': 'x', 'v': 1}
